                {0, 16, 13, 0, 0, 0},
                {0, 0, 10, 12, 0, 0},
                {0, 4, 0, 0, 14, 0},
                {0, 0, 9, 0, 0, 20},
                {0, 0, 0, 7, 0, 4},
                {0, 0, 0, 0, 0, 0},
        });
    }

    private static List<MaxFlowSolver> strategies() {
        return List.of(
                new FordFulkersonSolver(new BreadthFirstPathFinder()),
                new FordFulkersonSolver(new DepthFirstPathFinder()));
    }

